function solve(tree, k) {
  const sorted = [];
  function dfs(i) {
    if (i >= tree.length || tree[i] === null) return;
    dfs(2 * i + 1);
    sorted.push(tree[i]);
    dfs(2 * i + 2);
  }
  dfs(0);
  return sorted[k - 1];
}

